CREATE COLUMN TABLE "TEST_AP"."NNM5" ("ObjectCode" NVARCHAR(20) NOT NULL , "Series" INTEGER CS_INT NOT NULL , "DocSubType" NVARCHAR(2) DEFAULT '--' NOT NULL , "Number" INTEGER CS_INT NOT NULL , PRIMARY KEY ("Series", "ObjectCode", "DocSubType", "Number")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."NNM5" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$Series$Number$','Series','Number'));
CREATE INDEX "NNM5_SERIES" ON "TEST_AP"."NNM5" ( "Series" ASC, "Number" ASC )